# int <-> str conversion limits: sys.set_int_max_str_digits and its defaults.
import sys
print(sys.get_int_max_str_digits())
big = 10 ** 4299
digits = big.__repr__()
print(int(digits) == big)
sys.set_int_max_str_digits(0)
print(sys.get_int_max_str_digits())
huge = 10 ** 6000
print(int(huge.__repr__()) == huge)
sys.set_int_max_str_digits(700)
print(sys.get_int_max_str_digits())
print((10 ** 699).__repr__() == (10 ** 699).__repr__())
print(int('') == 10 ** 700 - 1)
print(int('', 16) == 16 ** 5000 - 1)
print((-(10 ** 699)).__repr__() == (-(10 ** 699)).__repr__())
sys.set_int_max_str_digits(maxdigits=640)
print(sys.get_int_max_str_digits())
sys.set_int_max_str_digits(5000)
print(int('') > 0)
sys.set_int_max_str_digits(4300)
(10 ** 4300).__repr__()
